DO $$ DECLARE n integer; BEGIN
 IF (SELECT count(*) FROM pg_policy WHERE polrelid='assignments'::regclass
   AND polname IN ('student_learning_read','student_learning_no_insert','student_learning_no_update','student_learning_no_delete') AND NOT polpermissive)<>4
 THEN RAISE EXCEPTION 'Student material read-only isolation policies missing'; END IF;
 IF (SELECT count(*) FROM pg_policy p WHERE p.polrelid IN ('marks'::regclass,'exams'::regclass)
   AND p.polname IN ('student_learning_read','student_learning_no_insert','student_learning_no_update','student_learning_no_delete')
   AND NOT p.polpermissive)<>8
 OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='subjects'::regclass AND polname='student_class_subjects' AND NOT polpermissive)
 THEN RAISE EXCEPTION 'Student learning read-only isolation policies missing'; END IF;
 IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='auth.users'::regclass AND tgname='auth_verified_email_changed' AND tgenabled='O') OR has_function_privilege('authenticated','app.account_credentials()','EXECUTE') OR has_function_privilege('app_platform','app.account_credentials()','EXECUTE') OR has_table_privilege('app_api','auth.users','SELECT') THEN RAISE EXCEPTION 'Account credentials or verified email synchronization incorrectly configured';END IF;
 SELECT count(*) INTO n FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE ns.nspname='public' AND c.relkind='r' AND NOT c.relname LIKE 'spatial_%' AND (NOT c.relrowsecurity OR NOT c.relforcerowsecurity);
 IF n>0 THEN RAISE EXCEPTION '% public tables do not force RLS',n; END IF;
 IF EXISTS(SELECT FROM pg_roles WHERE rolname IN ('app_api','app_device','app_worker','app_platform') AND (rolsuper OR rolbypassrls)) THEN RAISE EXCEPTION 'Application role bypasses RLS'; END IF;
 IF has_table_privilege('app_platform','students','SELECT') THEN RAISE EXCEPTION 'Platform can read student records'; END IF;
 IF has_table_privilege('app_api','audit_logs','UPDATE') OR has_table_privilege('app_api','attendance_events','DELETE') THEN RAISE EXCEPTION 'Audit mutability detected'; END IF;
 IF has_table_privilege('authenticated','students','SELECT') OR has_table_privilege('anon','students','SELECT') THEN RAISE EXCEPTION 'PostgREST access exposed'; END IF;
 IF NOT EXISTS(SELECT FROM information_schema.columns WHERE table_schema='public' AND table_name='students' AND column_name='gender' AND is_nullable='NO') OR NOT EXISTS(SELECT FROM pg_constraint WHERE conrelid='students'::regclass AND conname='students_gender_check') THEN RAISE EXCEPTION 'Student gender column or validation missing'; END IF;
 IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='student_parents'::regclass AND tgname='student_parent_limit' AND tgenabled='O') OR EXISTS(SELECT FROM pg_proc WHERE oid='app.enforce_student_parent_limit()'::regprocedure AND prosecdef) THEN RAISE EXCEPTION 'Two-parent limit trigger missing or incorrectly privileged'; END IF;
 IF NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='school_holidays'::regclass AND polname='calendar_read' AND NOT polpermissive) OR NOT EXISTS(SELECT FROM pg_indexes WHERE indexname='calendar_no_duplicate') THEN RAISE EXCEPTION 'Calendar isolation or duplicate guard missing'; END IF;
 IF has_table_privilege('authenticated','school_holidays','SELECT') OR has_table_privilege('anon','school_holidays','SELECT') OR has_function_privilege('app_api','app.calendar_class_reference_guard()','EXECUTE') THEN RAISE EXCEPTION 'Calendar privileged surface exposed'; END IF;
 IF NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='timetable_entries'::regclass AND polname='timetable_read' AND NOT polpermissive) OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='schools'::regclass AND tgname='timetable_settings_guard') OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='timetable_entries'::regclass AND tgname='timetable_entry_guard') THEN RAISE EXCEPTION 'Timetable guards or scope policy missing'; END IF;
 IF has_table_privilege('authenticated','timetable_entries','SELECT') OR has_table_privilege('anon','timetable_entries','INSERT') OR has_function_privilege('anon','app.valid_timetable_settings(jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Timetable browser surface exposed'; END IF;
 IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='fee_records'::regclass AND tgname='fee_record_guard') OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='fee_payments'::regclass AND tgname='balanced' AND tgdeferrable) OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='fee_records'::regclass AND polname='fee_read_scope' AND NOT polpermissive) THEN RAISE EXCEPTION 'Fee ledger guards or ownership policies missing';END IF;
 IF has_table_privilege('authenticated','fee_payments','SELECT') OR has_table_privilege('anon','fee_records','SELECT') OR has_table_privilege('app_api','fee_payments','UPDATE') OR has_function_privilege('anon','app.fee_writer(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Fee ledger exposed or mutable';END IF;
 IF NOT EXISTS(SELECT FROM pg_indexes WHERE indexname='one_active_card') OR NOT EXISTS(SELECT FROM pg_indexes WHERE indexname='card_uid_lookup') THEN RAISE EXCEPTION 'Card uniqueness missing'; END IF;
 IF NOT EXISTS(SELECT FROM pg_constraint WHERE conrelid='daily_attendance'::regclass AND contype='u' AND pg_get_constraintdef(oid) LIKE '%school_id, student_id, attendance_date%') THEN RAISE EXCEPTION 'Daily idempotency missing'; END IF;
 IF NOT EXISTS(SELECT FROM pg_constraint WHERE conrelid='attendance_events'::regclass AND contype='u' AND pg_get_constraintdef(oid) LIKE '%device_id, device_event_id%') THEN RAISE EXCEPTION 'Event idempotency missing'; END IF;
 IF EXISTS(SELECT FROM storage.buckets WHERE id IN ('school-documents','firmware') AND public) THEN RAISE EXCEPTION 'Private bucket exposed'; END IF;
 IF EXISTS(SELECT FROM pg_policy WHERE polrelid=to_regclass('storage.objects') AND polroles && ARRAY[0::oid,(SELECT oid FROM pg_roles WHERE rolname='anon'),(SELECT oid FROM pg_roles WHERE rolname='authenticated')]) THEN RAISE EXCEPTION 'Review direct browser storage policies; Vidyalayaa requires no user listing/read policy'; END IF;
 IF has_table_privilege('app_api','auth.sessions','SELECT') OR has_table_privilege('authenticated','app.login_session_activity','SELECT') OR has_table_privilege('app_platform','app.account_security_events','SELECT') OR has_function_privilege('authenticated','app.end_account_sessions(uuid,uuid,boolean)','EXECUTE') THEN RAISE EXCEPTION 'Private login sessions or controls exposed';END IF;
 IF NOT EXISTS(SELECT FROM pg_class WHERE oid='app.account_security_events'::regclass AND relrowsecurity AND relforcerowsecurity) OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='app.account_security_events'::regclass AND polname='own_security_events') THEN RAISE EXCEPTION 'Account security ownership protection missing';END IF;
 IF NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='students'::regclass AND polname='parent_read' AND NOT polpermissive)
 OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='marks'::regclass AND polname='parent_read' AND NOT polpermissive)
 OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='attendance_corrections'::regclass AND polname='parent_no_decision' AND NOT polpermissive)
 THEN RAISE EXCEPTION 'Parent ownership policies missing'; END IF;
 IF has_function_privilege('authenticated','app.parent_student_access(uuid,uuid)','EXECUTE')
 OR has_function_privilege('anon','app.parent_record_access(uuid,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Private parent ownership helper exposed'; END IF;
 IF to_regprocedure('app.parent_attendance_days(uuid,date,date)') IS NULL THEN RAISE EXCEPTION 'Parent attendance calendar missing'; END IF;
 IF has_function_privilege('authenticated','app.parent_attendance_days(uuid,date,date)','EXECUTE') OR has_function_privilege('anon','app.parent_attendance_days(uuid,date,date)','EXECUTE') THEN RAISE EXCEPTION 'Private attendance calendar exposed'; END IF;
 IF to_regprocedure('app.timetable_entry_labels(uuid,uuid)') IS NULL OR has_function_privilege('authenticated','app.timetable_entry_labels(uuid,uuid)','EXECUTE') OR has_function_privilege('anon','app.timetable_entry_labels(uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Timetable label privacy guard missing or exposed';END IF;
 IF (SELECT count(*) FROM pg_policy WHERE polname='student_profile_read' AND NOT polpermissive AND polrelid IN ('students'::regclass,'parents'::regclass,'student_parents'::regclass,'enrollments'::regclass,'classes'::regclass,'academic_sessions'::regclass))<>6 THEN RAISE EXCEPTION 'Student profile ownership policies missing'; END IF;
 IF has_function_privilege('authenticated','app.student_profile_record_access(uuid,text,uuid)','EXECUTE') OR has_function_privilege('anon','app.non_student_context(uuid)','EXECUTE') THEN RAISE EXCEPTION 'Private student ownership helper exposed';END IF;
 IF NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='subjects'::regclass AND polname='student_class_subjects' AND NOT polpermissive) OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgrelid='assignments'::regclass AND tgname='homework_class_subject_guard' AND tgenabled='O') OR (SELECT count(*) FROM pg_trigger WHERE tgname='assessment_class_subject_guard' AND tgenabled='O' AND tgrelid IN ('marks'::regclass,'exams'::regclass))<>2 THEN RAISE EXCEPTION 'Class subject visibility or assessment/homework scope guard missing';END IF;
 IF has_function_privilege('authenticated','app.class_subject_configured(uuid,uuid,uuid)','EXECUTE') OR has_function_privilege('anon','app.class_subject_configured(uuid,uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'Class subject helper exposed'; END IF;
END $$;

DO $$ BEGIN
 IF NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='notification_outbox'::regclass AND polname='notification_read' AND NOT polpermissive) OR NOT EXISTS(SELECT FROM pg_policy WHERE polrelid='notification_outbox'::regclass AND polname='custom_worker_protocol') THEN RAISE EXCEPTION 'Notification ownership or deployment guard missing';END IF;
 IF has_table_privilege('authenticated','notification_recipient_targets','SELECT') OR has_table_privilege('anon','school_notification_settings','SELECT') OR has_table_privilege('app_api','notification_recipient_targets','INSERT') OR has_function_privilege('authenticated','app.queue_custom_notification(text,text,uuid[],text,text)','EXECUTE') THEN RAISE EXCEPTION 'Notification privileged surface exposed';END IF;
END $$;
